-- Majuscule la începutul variantelor de răspuns (Exersează)
UPDATE question_translations SET options_json='["Tot vară, în exact același timp cu emisfera nordică.","Primăvară, cu zile care se lungesc treptat.","Iarnă, cu zile scurte și temperaturi scăzute.","Niciun anotimp, fiindcă sudul nu are anotimpuri."]' WHERE question_id='d18c800a-fd3f-417b-91df-44b89727d08e' AND locale='ro';
UPDATE question_translations SET options_json='["Culoarea solului, care arată doar cantitatea de humus, nu viteza de scurgere a apei prin el.","Reacția chimică a solului (pH-ul), acidă, neutră sau bazică, indiferent de textură.","Textura, dată de mărimea particulelor: nisipul are pori largi, apa trece ușor; argila o reține.","Cantitatea de humus din sol, care ține de fertilitate, nu de viteza de scurgere a apei."]' WHERE question_id='10a8dfb6-bf1b-480d-92f8-43ca02b42e30' AND locale='ro';
UPDATE question_translations SET options_json='["Pădure ecuatorială -> savană -> pădure de foioase -> taiga -> tundră","Tundră -> taiga -> pădure de foioase -> pădure ecuatorială, pornind dinspre pol","Savană -> pădure ecuatorială -> tundră -> taiga, în ordinea depărtării de Ecuator","Mediteraneană -> pădure ecuatorială -> savană -> tundră, în ordinea firească"]' WHERE question_id='9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a18' AND locale='ro';
UPDATE question_translations SET options_json='["A curs mereu la același nivel, fără să se adâncească deloc.","S-a adâncit în timp, lăsând vechile lunci suspendate ca terase.","A secat complet și a fost înlocuit, mai târziu, de altul.","Și-a lărgit numai albia, fără să taie deloc în adâncime."]' WHERE question_id='rm-q04' AND locale='ro';
UPDATE question_translations SET options_json='["O vale fluvială inundată de ploile foarte abundente.","Un golf îngust săpat în stâncă de valurile mării.","Un crater vulcanic vechi, umplut cu apă sărată.","O vale glaciară adâncă, invadată apoi de apa mării."]' WHERE question_id='rm-q11' AND locale='ro';
UPDATE question_translations SET options_json='["Vântul erodează mai tare aproape de sol, unde cară nisipul.","Roca crește de la sine, întocmai ca o ciupercă de pădure.","Gheața taie baza stâncii în timpul iernilor foarte lungi.","Ploaia sapă partea de sus a stâncii și o subțiază mult."]' WHERE question_id='rm-q16' AND locale='ro';
UPDATE question_translations SET options_json='["Înaintează treptat în mare, câștigând tot mai mult teren nou.","Rămâne neschimbată, fiindcă valurile nu o pot roade deloc.","Se retrage spre uscat, lăsând în față o platformă de abraziune.","Se transformă, încet, într-o deltă largă, cu multe brațe."]' WHERE question_id='rm-q20' AND locale='ro';
UPDATE question_translations SET options_json='["Un râu sapă în adâncime și taie o vale îngustă în roca dură.","Gheața topește uscatul de la marginea mării, în nordul rece.","Valurile taie o faleză abruptă în țărmul înalt și stâncos.","Un cordon de nisip închide un golf, izolând un lac lângă țărm."]' WHERE question_id='rm-q22' AND locale='ro';
UPDATE question_translations SET options_json='["Dizolvarea rocii de către apa de ploaie, întocmai ca la calcar.","Acțiunea îngheț-dezgheț și a vântului, care roade inegal roca.","Depunerea de aluviuni aduse de râuri în timpul viiturilor.","Erupțiile vulcanice care au zguduit munții în trecutul geologic."]' WHERE question_id='rm-q26' AND locale='ro';
UPDATE question_translations SET options_json='["Lava s-a răcit și s-a contractat, crăpând în prisme regulate.","Apa curgătoare le-a șlefuit până când au ajuns drepte.","Au fost tăiate de oameni, în cariere foarte vechi de piatră.","Au crescut încet, întocmai ca niște cristale mari de sare."]' WHERE question_id='rm-q27' AND locale='ro';
UPDATE question_translations SET options_json='["Faliată: blocuri ridicate și blocuri coborâte între falii.","Tabulară, cu strate orizontale, nedeformate de mișcări.","Cutată, cu strate îndoite în anticlinale și sinclinale.","Monoclinală, cu strate înclinate toate în același sens."]' WHERE question_id='rm-q30' AND locale='ro';
UPDATE question_translations SET options_json='["Sunt create direct de om, prin exploatare și construcție.","Au apărut de la sine, cu trecerea a mii și mii de ani.","Sunt modelate de ghețarii care coborau odinioară din munți.","Sunt forme carstice, săpate în calcar prin dizolvare."]' WHERE question_id='rm-q33' AND locale='ro';
UPDATE question_translations SET options_json='["Se aduna și se năștea ghețarul, săpând roca cu greutatea lui.","Râul se varsă în mare și își depune acolo toate aluviunile.","Vântul a adunat nisipul într-un singur loc bine adăpostit.","S-a produs, cu foarte mult timp în urmă, o erupție vulcanică."]' WHERE question_id='rm-q37' AND locale='ro';
UPDATE question_translations SET options_json='["Fertilitatea, capacitatea solului de a hrăni plantele, cea mai importantă însușire a lui.","Structura, felul în care particulele solului se leagă între ele în agregate mai mari.","Porozitatea, spațiile goale dintre particulele solului prin care circulă apa și aerul.","Reacția chimică (pH-ul) a solului, care arată dacă acesta este acid, neutru sau bazic."]' WHERE question_id='c068bdd8-320e-4cc7-b1ba-81bed2600285' AND locale='ro';
